UPDATE home_banners SET eyebrow_json = '{"en": "The Ageless Reading Collection", "zh": "去老年化老花镜系列", "es": "La colección de lectura sin edad", "fr": "La collection de lecture intemporelle", "de": "Die zeitlose Lesebrillen-Kollektion", "it": "La collezione di lettura senza età", "pt": "A coleção de leitura atemporal", "ja": "年齢を感じさせない老眼鏡コレクション", "ko": "나이를 잊은 돋보기 컬렉션", "ar": "مجموعة نظارات القراءة الخالدة"}', title_json = '{"en": "Reading glasses, refreshingly modern.", "zh": "老花，也可以很时尚。", "es": "Gafas de lectura, sorprendentemente modernas.", "fr": "Lunettes de lecture, étonnamment modernes.", "de": "Lesebrillen — erfrischend modern.", "it": "Occhiali da lettura, sorprendentemente moderni.", "pt": "Óculos de leitura, surpreendentemente modernos.", "ja": "老眼鏡が、こんなにモダンに。", "ko": "돋보기가, 이렇게 모던할 수 있다.", "ar": "نظارات قراءة عصرية بشكل مدهش."}', sub_json = '{"en": "Lightweight, modern frames designed for the 45–60 generation. Pro lenses, fair prices, free worldwide shipping.", "zh": "为 45–60 岁年轻一代重新设计的轻量、简约、时尚老花镜与近视镜。专业镜片，平价直达。", "es": "Monturas ligeras y modernas diseñadas para la generación de 45 a 60. Lentes profesionales, precios justos, envío gratis en todo el mundo.", "fr": "Montures légères et modernes conçues pour la génération 45–60. Verres pro, prix justes, livraison mondiale gratuite.", "de": "Leichte, moderne Fassungen für die 45–60-Generation. Profi-Gläser, faire Preise, weltweit kostenloser Versand.", "it": "Montature leggere e moderne pensate per la generazione 45–60. Lenti pro, prezzi onesti, spedizione gratuita in tutto il mondo.", "pt": "Armações leves e modernas, pensadas para a geração 45–60. Lentes pro, preços justos, envio gratuito mundial.", "ja": "45–60 代に向けて再設計された軽量・モダンなフレーム。プロ仕様レンズ、公正な価格、世界中送料無料。", "ko": "45–60세대를 위해 다시 디자인한 가볍고 모던한 프레임. 프로 렌즈, 정직한 가격, 전 세계 무료 배송.", "ar": "إطارات خفيفة وعصرية مصمّمة لجيل 45–60. عدسات احترافية، أسعار عادلة، شحن مجاني حول العالم."}' WHERE id = 'hb-1';
UPDATE home_banners SET eyebrow_json = '{"en": "Everyday Eyeglasses", "zh": "日常通勤系列", "es": "Gafas para el día a día", "fr": "Lunettes du quotidien", "de": "Alltagsbrillen", "it": "Occhiali per ogni giorno", "pt": "Óculos para o dia a dia", "ja": "デイリー アイウェア", "ko": "데일리 아이웨어", "ar": "نظارات للاستخدام اليومي"}', title_json = '{"en": "One pair for every moment.", "zh": "一副陪你走遍每一天。", "es": "Un par para cada momento.", "fr": "Une paire pour chaque moment.", "de": "Eine Brille für jeden Moment.", "it": "Un paio per ogni momento.", "pt": "Um par para cada momento.", "ja": "いつもの一日に、一本。", "ko": "매 순간에, 하나의 안경.", "ar": "نظارة واحدة لكل لحظة."}', sub_json = '{"en": "Minimal frames with crisp optical lenses—at home, at work, on the go.", "zh": "简约镜框搭配高清光学镜片，办公、出行、日常无缝切换。", "es": "Monturas minimalistas con lentes ópticas nítidas — en casa, en el trabajo, en cualquier lugar.", "fr": "Des montures minimalistes avec des verres optiques nets — à la maison, au bureau, en déplacement.", "de": "Minimalistische Fassungen mit gestochen scharfen Gläsern — zu Hause, im Büro, unterwegs.", "it": "Montature minimal con lenti ottiche nitide — a casa, al lavoro, in movimento.", "pt": "Armações minimalistas com lentes ópticas nítidas — em casa, no trabalho, em movimento.", "ja": "クリアな光学レンズと、ミニマルなフレーム。自宅でも、仕事でも、移動中でも。", "ko": "미니멀한 프레임에 선명한 광학 렌즈 — 집에서, 직장에서, 어디서나.", "ar": "إطارات بسيطة وعدسات بصرية واضحة — في المنزل أو العمل أو في التنقّل."}' WHERE id = 'hb-2';
UPDATE home_banners SET eyebrow_json = '{"en": "Modern Myopia", "zh": "近视镜系列", "es": "Miopía moderna", "fr": "Myopie moderne", "de": "Moderne Kurzsichtigkeit", "it": "Miopia moderna", "pt": "Miopia moderna", "ja": "モダン マイオピア", "ko": "모던 마이오피아", "ar": "قِصر النظر العصري"}', title_json = '{"en": "See sharper. Wear lighter.", "zh": "清晰世界，轻巧上镜。", "es": "Ve más nítido. Lleva menos peso.", "fr": "Voir plus net. Porter plus léger.", "de": "Schärfer sehen. Leichter tragen.", "it": "Vedi più nitido. Indossa più leggero.", "pt": "Veja mais nítido. Use mais leve.", "ja": "視界はくっきり、フレームは軽やか。", "ko": "더 선명하게, 더 가볍게.", "ar": "رؤية أوضح، إحساس أخفّ."}', sub_json = '{"en": "Featherweight metal & acetate frames paired with high-index lenses you can wear all day.", "zh": "轻量金属与醋酸纤维镜框,配合超薄高折射率镜片,一整天都不累。", "es": "Monturas ligerísimas de metal y acetato con lentes de alto índice para llevar todo el día.", "fr": "Montures ultra-légères en métal et acétate avec verres haut indice à porter toute la journée.", "de": "Federleichte Fassungen aus Metall und Acetat mit hochbrechenden Gläsern — den ganzen Tag bequem.", "it": "Montature leggerissime in metallo e acetato con lenti ad alto indice da indossare tutto il giorno.", "pt": "Armações ultraleves de metal e acetato com lentes de alto índice para usar o dia todo.", "ja": "羽のように軽い金属とアセテートのフレームに、薄型高屈折レンズ。一日中つけても疲れません。", "ko": "깃털처럼 가벼운 메탈·아세테이트 프레임에 고굴절 렌즈. 하루 종일 편안하게.", "ar": "إطارات معدنية وأسيتاتية خفيفة كالريشة مع عدسات عالية الانكسار — مريحة طوال اليوم."}' WHERE id = 'hb-3';
UPDATE home_banners SET eyebrow_json = '{"en": "Editor''s Pick", "zh": "本季编辑精选", "es": "Selección del editor", "fr": "Sélection de la rédaction", "de": "Redaktionstipp", "it": "Selezione dell''editore", "pt": "Seleção do editor", "ja": "エディターズ ピック", "ko": "에디터의 선택", "ar": "اختيار المحرّر"}', title_json = '{"en": "Small details. Big difference.", "zh": "小细节,大改变。", "es": "Detalles pequeños. Gran diferencia.", "fr": "Petits détails. Grande différence.", "de": "Kleine Details. Großer Unterschied.", "it": "Piccoli dettagli. Grande differenza.", "pt": "Pequenos detalhes. Grande diferença.", "ja": "細部にこそ、違いがある。", "ko": "작은 디테일, 큰 차이.", "ar": "تفاصيل صغيرة، فرق كبير."}', sub_json = '{"en": "Hand-picked by our stylists—classic silhouettes with a modern twist.", "zh": "由我们的造型师精选——经典轮廓,现代线条,越戴越喜欢。", "es": "Elegidas a mano por nuestros estilistas — siluetas clásicas con un toque moderno.", "fr": "Sélectionnées par nos stylistes — silhouettes classiques revisitées avec modernité.", "de": "Von unseren Stylisten handverlesen — klassische Formen mit modernem Twist.", "it": "Selezionati a mano dai nostri stylist — silhouette classiche con un tocco moderno.", "pt": "Selecionados a dedo pelos nossos estilistas — silhuetas clássicas com um toque moderno.", "ja": "当社のスタイリストが厳選 — クラシックなシルエットにモダンなアクセント。", "ko": "우리 스타일리스트가 직접 고른 — 클래식한 실루엣에 모던한 감각.", "ar": "اختارها فريق التصميم لدينا بعناية — صياغات كلاسيكية بلمسة عصرية."}' WHERE id = 'hb-4';
